steps.script:
$l=@(Get-Content 'C:\TTiTTulares\ttittulares-mobile-trigger.log' -Tail 500)
$id='tt-draftbackup-1794482993257';$idx=-1
for($i=0;$i -lt $l.Count;$i++){if($l[$i] -match ('LAUNCH FAILED.*'+$id)){$idx=$i}}
$o=@{state='not_found';reason='unknown';backup=$false}
if($idx -ge 0){$o.state='failed';$lo=[Math]::Max(0,$idx-20);$seg=@($l[$lo..$idx]);$joined=$seg -join ' '
foreach($k in @('RESTORED_DRAFT_TOO_LARGE','RESTORED_DRAFT_BACKUP_EXISTS','RESTORED_DRAFT_FOCUS_FAILED','RESTORED_DRAFT_CLEAR_UNVERIFIED','Fresh tab has draft or chat content','OTHER_CHAT_ACTIVITY','NEW_CHAT_CONTROL_UNAVAILABLE','CHAT MESSAGE TIMEOUT','No aparece el cuadro de escritura','COMPOSER_NOT_FOCUSED')){if($joined.Contains($k)){$o.reason=$k}}
$o.backup=$joined.Contains('RESTORED_DRAFT_BACKED_UP_LOCAL')
}
Write-Output ('TTRESULT:'+($o|ConvertTo-Json -Compress))
